import React, { useState, useRef, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "./Ho.css";

const images = Array.from({ length: 24 }, (_, i) => `/images/a${i + 1}.gif`);

// Function to get dominant colors from an image
const getDominantColors = (imageUrl, numColors = 5) => {
  return new Promise((resolve) => {
    const img = new Image();
    img.crossOrigin = "Anonymous";
    img.onload = () => {
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');
      canvas.width = img.width;
      canvas.height = img.height;
      ctx.drawImage(img, 0, 0);

      const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const pixels = imageData.data;
      const colorCounts = {};

      // Sample pixels (every 10th pixel for performance)
      for (let i = 0; i < pixels.length; i += 40) {
        const r = pixels[i];
        const g = pixels[i + 1];
        const b = pixels[i + 2];
        const key = `${r},${g},${b}`;
        colorCounts[key] = (colorCounts[key] || 0) + 1;
      }

      // Sort colors by frequency
      const sortedColors = Object.entries(colorCounts)
        .sort(([, a], [, b]) => b - a)
        .slice(0, numColors)
        .map(([color]) => {
          const [r, g, b] = color.split(',').map(Number);
          return `rgb(${r},${g},${b})`;
        });

      resolve(sortedColors);
    };
    img.src = imageUrl;
  });
};

function Home() {
  const [selectedImages, setSelectedImages] = useState([]);
  const [uploadedImages, setUploadedImages] = useState([]);
  const [imageColors, setImageColors] = useState({});
  const fileInputRef = useRef();
  const navigate = useNavigate();

  // Load uploaded images from localStorage on component mount
  useEffect(() => {
    const savedImages = localStorage.getItem('uploadedImages');
    if (savedImages) {
      setUploadedImages(JSON.parse(savedImages));
    }
  }, []);

  // Save uploaded images to localStorage whenever they change
  useEffect(() => {
    localStorage.setItem('uploadedImages', JSON.stringify(uploadedImages));
  }, [uploadedImages]);

  // Load and process colors for all images
  useEffect(() => {
    const loadColors = async () => {
      const allImages = [...images, ...uploadedImages.map(img => img.url)];
      const colors = {};

      for (const imgUrl of allImages) {
        if (!imageColors[imgUrl]) {
          const dominantColors = await getDominantColors(imgUrl);
          colors[imgUrl] = dominantColors;
        }
      }

      setImageColors(prev => ({ ...prev, ...colors }));
    };

    loadColors();
  }, [uploadedImages]);

  const handleFileUpload = async (event) => {
    const files = Array.from(event.target.files);

    for (const file of files) {
      if (file.type.startsWith('image/')) {
        const reader = new FileReader();

        reader.onload = (e) => {
          const imageUrl = e.target.result;
          setUploadedImages(prev => [...prev, {
            url: imageUrl,
            timestamp: new Date().toISOString()
          }]);
        };

        reader.readAsDataURL(file);
      }
    }
  };

  const toggleImage = (img) => {
    setSelectedImages((prev) => {
      if (prev.includes(img)) {
        return prev.filter((i) => i !== img);
      } else if (prev.length < 3) {
        return [...prev, img];
      }
      return prev;
    });
  };

  const generateImage = () => {
    if (selectedImages.length === 0) return;

    // Create a temporary canvas to stack images
    const canvas = document.createElement('canvas');
    canvas.width = 1080;
    canvas.height = 1080;
    const ctx = canvas.getContext('2d');

    // Fill with white background
    ctx.fillStyle = 'white';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Load and stack images
    let loadedImages = 0;
    selectedImages.forEach(imgUrl => {
      const img = new Image();
      img.crossOrigin = "Anonymous";
      img.onload = () => {
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        loadedImages++;

        // Only save and navigate when all images are loaded
        if (loadedImages === selectedImages.length) {
          localStorage.setItem("generatedImage", canvas.toDataURL());
          navigate("/generate");
        }
      };
      img.src = imgUrl;
    });
  };

  const removeUploadedImage = (index) => {
    setUploadedImages(prev => prev.filter((_, i) => i !== index));
  };

  return (
    <div className="ho-container">
    <div className="ho-title-container">
    <h1 className="ho-title">Graphic Archive</h1>
    <div className="ho-generate-container">


      <div className="ho-selection-info">
        Selected: {selectedImages.length}/3 images
      </div>
      <button
        className="ho-generate-button"
        onClick={generateImage}
        disabled={selectedImages.length === 0}
      >
        Generate
      </button>
      </div>
      </div>

    <div className="ho-main">
      <div className="box1">

        <h1 className="ho-list" onClick={() => navigate('/archive')} style={{ cursor: 'pointer' }}>Archive</h1>
        <h1 className="ho-list" onClick={() => navigate('/about')} style={{ cursor: 'pointer' }}>About</h1>



      <div className="ho-upload-section">
        <input
          type="file"
          ref={fileInputRef}
          onChange={handleFileUpload}
          accept="image/*"
          multiple
          style={{ display: 'none' }}
        />
        <button
          className="ho-upload-button"
          onClick={() => fileInputRef.current.click()}
        >
          Upload gif!
        </button>
      </div>


      </div>





      <div className="ho-grid">
        {/* Display existing images */}
        {images.map((img, i) => {
          const selectedIndex = selectedImages.indexOf(img);
          return (
            <div key={`existing-${i}`} className="ho-image-container">
              <img
                src={img}
                alt={`tile-${i}`}
                onClick={() => toggleImage(img)}
                className={`ho-image ${selectedIndex !== -1 ? 'selected' : ''}`}
              />
              {selectedIndex !== -1 && (
                <div className="ho-image-number">
                  {selectedIndex + 1}
                </div>
              )}
              {imageColors[img] && (
                <div className="color-swatches">
                  {imageColors[img].map((color, index) => (
                    <div
                      key={index}
                      className="color-swatch"
                      style={{ backgroundColor: color }}
                    />
                  ))}
                </div>
              )}
            </div>
          );
        })}

        {/* Display uploaded images */}
        {uploadedImages.map((img, i) => {
          const selectedIndex = selectedImages.indexOf(img.url);
          return (
            <div key={`uploaded-${i}`} className="ho-image-container">
              <img
                src={img.url}
                alt={`uploaded-${i}`}
                onClick={() => toggleImage(img.url)}
                className={`ho-image ${selectedIndex !== -1 ? 'selected' : ''}`}
              />
              {selectedIndex !== -1 && (
                <div className="ho-image-number">
                  {selectedIndex + 1}
                </div>
              )}
              <button
                className="ho-remove-button"
                onClick={(e) => {
                  e.stopPropagation();
                  removeUploadedImage(i);
                }}
              >

              </button>
              {img.timestamp && (
                <div className="ho-timestamp">
                  {new Date(img.timestamp).toLocaleString()}
                </div>
              )}
              {imageColors[img.url] && (
                <div className="color-swatches">
                  {imageColors[img.url].map((color, index) => (
                    <div
                      key={index}
                      className="color-swatch"
                      style={{ backgroundColor: color }}
                    />
                  ))}
                </div>
              )}
            </div>
          );
        })}
      </div>
      </div>
    </div>
  );
}

export default Home;
